const t = computed(() => translations[lang.value] || translations.en)
const service = computed(() => t.value.services[activeService.value])
watch(lang, () => { activeService.value = 0 })

function initReveal() {
  observer?.disconnect()
  const elements = document.querySelectorAll('.ps-services .sv-reveal')
  if (!('IntersectionObserver' in window)) {
    elements.forEach(el => el.classList.add('sv-visible'))
    return
  }
  observer = new IntersectionObserver(entries => {
    for (const entry of entries) {
      if (entry.isIntersecting) { entry.target.classList.add('sv-visible'); observer.unobserve(entry.target) }
    }
  }, { threshold: .1 })
  elements.forEach(el => observer.observe(el))
}
onMounted(async () => { await nextTick(); initReveal() })
onBeforeUnmount(() => observer?.disconnect())
